Lemma meas_val : forall c E1 R1 (M1 : mem) cls, CC.At (hl_segs L) c E1 R1 M1 -> env_agree GT.NF E0 E1 -> PSM4.meas_cls c = Some cls ->
  match cls with
  | inl z => CC.meas c E1 = z
  | inr z0 => CC.meas c E1 = 64 * uv E1 (EVar 49) + 8 * uv E1 (EVar 50) + z0 /\ 0 <= uv E1 (EVar 49) <= wlen /\ 0 <= uv E1 (EVar 50) <= 3 /\ uv E1 PSM4.CURJ = wend - uv E1 (EVar 49) /\ 5 <= z0 <= 9
  end.
